sudo incus exec qdrant -- python3 -c "
import urllib.request, json

collections = json.load(urllib.request.urlopen('http://127.0.0.1:6333/collections'))['result']['collections']
all_repos = {}

for coll in collections:
    name = coll['name']
    if 'voyage' not in name and name not in ('code_lsp', 'compliance_general', 'compliance_official'):
        continue

    offset = None
    repos = {}
    while True:
        body = {'limit': 500, 'with_payload': {'include': ['repo']}, 'with_vector': False}
        if offset:
            body['offset'] = offset
        req = urllib.request.Request(f'http://127.0.0.1:6333/collections/{name}/points/scroll',
            data=json.dumps(body).encode(), headers={'Content-Type':'application/json'}, method='POST')
        try:
            resp = json.load(urllib.request.urlopen(req))
        except:
            break
        for p in resp['result']['points']:
            r = p.get('payload', {}).get('repo', 'UNKNOWN')
            repos[r] = repos.get(r, 0) + 1
        offset = resp['result'].get('next_page_offset')
        if not offset:
            break

    for r, count in repos.items():
        if r not in all_repos:
            all_repos[r] = {}
        all_repos[r][name] = count

# Print sorted
for repo in sorted(all_repos.keys()):
    colls = all_repos[repo]
    total = sum(colls.values())
    coll_str = ', '.join(f'{c}:{v}' for c,v in sorted(colls.items()))
    print(f'{repo:60s} {total:>8,}  [{coll_str}]')
" 2>&1 | head -80

